import {sciencePanel,scienceRadio,missionBudget} from './science.mjs';
import {bindTerrainMaterial} from './appearance.mjs';
import {makeTerrain,inside,groundAt,linkProfile,resolveRadio,PRESETS} from './physics.mjs';
const $=id=>document.getElementById(id),base=[3500,3500],goal=[1700,3500],goal2=[2400,4100];let radio=scienceRadio('video');let terrain,pending=null,relays=[],update3d=()=>{};
const science=sciencePanel(mode=>{radio=scienceRadio(mode);invalidate();draw();if(pending)choosePoint(pending);});
function evaluate(a,b,h1,h2){const v=linkProfile(terrain,radio,...a,h1,...b,h2,terrain.res);const valid=v.D>30&&[...v.d,...v.zFlat].every(Number.isFinite),gap=Math.max(...Array.from(v.d,(d,i)=>v.zFlat[i]-(v.za+(v.zb-v.za)*d/v.D)).slice(1,-1));return {v,valid,visible:valid&&gap<=0,ok:valid&&Number.isFinite(v.margin)&&v.margin>=3};}
function chart(title,a,b,h1,h2){const {v}=evaluate(a,b,h1,h2),z=[...v.zFlat,v.za,v.zb].filter(Number.isFinite),lo=Math.min(...z)-5,hi=Math.max(...z)+5,x=d=>40+620*d/v.D,y=h=>170-140*(h-lo)/(hi-lo),pts=[...v.d].map((d,i)=>`${x(d)},${y(v.zFlat[i])}`).join(' ');return `<article class="profile-card"><h3>${title}</h3><svg viewBox="0 0 700 205" role="img" aria-label="${title} 지형 단면"><polyline points="${pts}" fill="none" stroke="#f4ac78" stroke-width="3"/><line x1="40" y1="${y(v.za)}" x2="660" y2="${y(v.zb)}" stroke="#8cd7b0" stroke-width="2"/></svg><p>주황: 지형 · 초록: 안테나 사이 직선</p></article>`;}
function invalidate(){ sessionStorage.removeItem('mars-level4-relays');sessionStorage.removeItem('mars-science-mode'); $('result').hidden=true;$('lines').innerHTML='';if(window.parent!==window)window.parent.postMessage({type:'level4-result',success:false},location.origin);}
function draw(){ if(terrain)science.update(terrain,relays); $('count').textContent=`설치 ${relays.length} / 2개`;$('check').disabled=!relays.length;$('install').disabled=!pending||relays.length>=2;$('markers').innerHTML=[['기지',base,'#fff'],...relays.map((p,i)=>[`중계 ${i+1}`,p,'#f4ac78']),['팀 1',goal,'#ff8666'],['팀 2',goal2,'#caaaff'],...(pending?[['조사 중',pending,'#ffd166']]:[])].map(([id,[x,y],color])=>`<circle cx="${x}" cy="${y}" r="55" fill="${color}" stroke="#111" stroke-width="10"/><text x="${x+65}" y="${y-40}" fill="white" font-size="75">${id}</text>`).join('');$('remove').replaceChildren();relays.forEach((p,i)=>{const b=document.createElement('button');b.className='candidate';b.textContent=`중계소 ${i+1} 철거`;b.onclick=()=>{relays.splice(i,1);pending=null;$('preview').hidden=true;invalidate();draw()};$('remove').append(b)});update3d();}
function choosePoint(p){if(!terrain)return;if(relays.length>=2){$('status').textContent='장비를 모두 설치했습니다. 위치를 바꾸려면 중계소를 철거하세요.';return;}const others=[['기지',base,4],...relays.map((q,i)=>[`중계소 ${i+1}`,q,3]),['팀 1',goal,2],['팀 2',goal2,2]];if(!inside(terrain,...p)||others.some(([,q])=>Math.hypot(q[0]-p[0],q[1]-p[1])<30)||others.some(([,q,h])=>!evaluate(q,p,h,3).valid)){$('status').textContent='자료가 없거나 다른 지점에 너무 가깝습니다. 다른 위치를 선택하세요.';return;}pending=p;invalidate();draw();$('status').textContent=`조사 위치: 동쪽 ${Math.round(p[0])}m · 남쪽 ${Math.round(p[1])}m. 조사 결과를 살펴본 뒤 설치하세요.`;$('preview').hidden=false;$('preview').innerHTML=`<h2>설치 전 지형 조사</h2>${science.describe(terrain,p)}<p>선택 지점 고도 약 ${Math.round(groundAt(terrain,...p))}m. 주황 지형이 초록 직선을 넘으면 가시선이 가려집니다. 가려져도 회절 후 신호 여유가 3dB 이상이면 연결됩니다. 높이는 보기 쉽게 확대되었습니다.</p>${others.map(([name,q,h])=>{const e=evaluate(q,p,h,3);return `<p><strong>${name} → 조사 지점:</strong> 가시선 ${e.visible?'확보':'지형에 가림'} · 신호 여유 ${e.v.margin.toFixed(1)} dB (${e.v.margin>=3?(e.visible?'기준 충족':'회절 후 기준 충족'):'기준 미달'})</p><details><summary>${name} 구간 단면 보기</summary>${chart(`${name} → 조사 지점`,q,p,h,3)}</details>`}).join('')}`;}
$('map').addEventListener('click',e=>{const svg=$('map'),pt=svg.createSVGPoint();pt.x=e.clientX;pt.y=e.clientY;const p=pt.matrixTransform(svg.getScreenCTM().inverse());choosePoint([p.x,p.y]);});
$('install').onclick=()=>{if(!pending||relays.length>=2)return;relays.push(pending);pending=null;$('preview').hidden=true;$('status').textContent='중계소를 설치했습니다. 다음 위치를 조사하거나 결과를 확인하세요.';invalidate();draw()};
$('reset').onclick=()=>{pending=null;relays=[];$('preview').hidden=true;$('status').textContent='지도에서 조사할 위치를 눌러주세요.';invalidate();draw()};
$('check').onclick=()=>{const nodes=[{name:'기지',p:base,h:4},...relays.map((p,i)=>({name:`중계소 ${i+1}`,p,h:3})),{name:'팀 1',p:goal,h:2},{name:'팀 2',p:goal2,h:2}],edges=[];for(let i=0;i<nodes.length;i++)for(let j=i+1;j<nodes.length;j++)edges.push({a:i,b:j,...evaluate(nodes[i].p,nodes[j].p,nodes[i].h,nodes[j].h)});const queue=[[0]],seen=new Set([0]),routes={};while(queue.length){const path=queue.shift(),last=path.at(-1);if(last>=nodes.length-2){routes[last]=path;continue;}for(const e of edges){if(!e.ok)continue;const n=e.a===last?e.b:e.b===last?e.a:null;if(n!==null&&!seen.has(n)){seen.add(n);queue.push([...path,n]);}}}const connected=!!(routes[nodes.length-2]&&routes[nodes.length-1]);const route=connected&&missionBudget(terrain,relays,science.mode).ok;$('lines').innerHTML=edges.map(e=>`<line x1="${nodes[e.a].p[0]}" y1="${nodes[e.a].p[1]}" x2="${nodes[e.b].p[0]}" y2="${nodes[e.b].p[1]}" stroke="${e.ok?(e.visible?'#8cd7b0':'#ffc45e'):'#ff876c'}" stroke-dasharray="${e.ok&&e.visible?'0':'40 35'}" stroke-width="15"/>`).join('');$('result').hidden=false;$('result').innerHTML=`<h2>${route?'과학 탐사 기록 확보 성공':connected?'연결 확보 · 작업 시간 재검토':'목표까지 연결되지 않았어요'}</h2><p>${route?'연결 경로: '+routes[nodes.length-2].map(i=>nodes[i].name).join(' → ')+' / '+routes[nodes.length-1].map(i=>nodes[i].name).join(' → '):connected?'통신 경로는 확보했습니다. 아래 작업 시간과 전송 방식을 비교하세요.':'구간별 결과를 보고 중계소를 추가하거나 다른 위치에 설치해 보세요.'}</p>${science.report(terrain,relays,connected)}<details><summary>구간별 결과 보기</summary><ul>${edges.map(e=>`<li>${nodes[e.a].name} → ${nodes[e.b].name}: ${!e.valid?'지형 자료 부족':`가시선 ${e.visible?'확보':'가림'} · 신호 여유 ${e.v.margin.toFixed(1)} dB${e.ok&&!e.visible?' · 회절 후 신호 충분':''}`}</li>`).join('')}</ul></details><p>고도 표본과 교육용 장비 설정을 이용한 시뮬레이션입니다.</p>`;if(route){sessionStorage.setItem('mars-level4-relays',JSON.stringify(relays));sessionStorage.setItem('mars-science-mode',science.mode);}if(window.parent!==window)window.parent.postMessage({type:'level4-result',success:!!route},location.origin);};
try{const [m,b]=await Promise.all([fetch('./data/meta.json').then(r=>{if(!r.ok)throw Error();return r.json()}),fetch('./data/terrain_8m.f32').then(r=>{if(!r.ok)throw Error();return r.arrayBuffer()})]);terrain=makeTerrain(b,m);if(![base,goal,goal2].every(p=>inside(terrain,...p)))throw Error();draw();init3d().catch(()=>{$('terrain3d').textContent='3D 지형을 불러오지 못했습니다. 아래 2D 지도를 이용해 주세요.'})}catch(e){$('result').hidden=false;$('result').textContent='지형 자료를 불러오지 못했습니다.'}

async function init3d(){const THREE=await import('https://cdn.jsdelivr.net/npm/three@0.160.0/build/three.module.js');const {OrbitControls}=await import('https://cdn.jsdelivr.net/npm/three@0.160.0/examples/jsm/controls/OrbitControls.js');const el=$('terrain3d'),h=330,renderer=new THREE.WebGLRenderer({antialias:true});renderer.setPixelRatio(Math.min(devicePixelRatio,2));renderer.setSize(el.clientWidth||600,h);el.replaceChildren(renderer.domElement);const scene=new THREE.Scene();scene.background=new THREE.Color(0x161c19);const camera=new THREE.PerspectiveCamera(42,(el.clientWidth||600)/h,1,20000);camera.position.set(1800,2100,2300);const controls=new OrbitControls(camera,renderer.domElement);controls.enableDamping=true;scene.add(new THREE.HemisphereLight(0xffffff,0x493224,2));const center=groundAt(terrain,2750,4250),n=100,positions=[],uv=[],idx=[];for(let j=0;j<=n;j++)for(let i=0;i<=n;i++){const x=1500+2500*i/n,y=3000+2500*j/n,z=groundAt(terrain,x,y);positions.push(x-2750,(Number.isFinite(z)?z-center:0)*2,y-4250);uv.push(x/(terrain.w*terrain.res),1-y/(terrain.h*terrain.res));if(i<n&&j<n){let k=j*(n+1)+i;idx.push(k,k+n+1,k+1,k+1,k+n+1,k+n+2)}}const g=new THREE.BufferGeometry();g.setAttribute('position',new THREE.Float32BufferAttribute(positions,3));g.setAttribute('uv',new THREE.Float32BufferAttribute(uv,2));g.setIndex(idx);g.computeVertexNormals();const tex=await new THREE.TextureLoader().loadAsync('data/ortho_4m.jpg');tex.colorSpace=THREE.SRGBColorSpace;const terrainMaterial=new THREE.MeshStandardMaterial({map:tex,side:THREE.DoubleSide});bindTerrainMaterial(terrainMaterial);const mesh=new THREE.Mesh(g,terrainMaterial);scene.add(mesh);const group=new THREE.Group();scene.add(group);const point=(p,h=0)=>new THREE.Vector3(p[0]-2750,(groundAt(terrain,...p)+h-center)*2,p[1]-4250);function label(text){const c=document.createElement('canvas');c.width=512;c.height=128;const x=c.getContext('2d');x.fillStyle='rgba(12,20,16,.88)';x.fillRect(0,5,512,118);x.fillStyle='white';x.textAlign='center';x.textBaseline='middle';x.font='bold 54px sans-serif';x.fillText(text,256,65);const spr=new THREE.Sprite(new THREE.SpriteMaterial({map:new THREE.CanvasTexture(c),depthTest:false,transparent:true}));spr.scale.set(430,108,1);spr.renderOrder=10;return spr;}update3d=()=>{while(group.children.length){let o=group.children[0];group.remove(o);if(o.geometry)o.geometry.dispose();if(o.material){if(o.material.map)o.material.map.dispose();o.material.dispose()}}for(const [name,p,color] of [['기지',base,0xffffff],...relays.map((p,i)=>[`중계소 ${i+1}`,p,0xf4ac78]),['팀 1',goal,0xff8666],['팀 2',goal2,0xcaaaff],...(pending?[['조사 위치',pending,0xffd166]]:[])]){let mark=new THREE.Mesh(new THREE.SphereGeometry(35,12,8),new THREE.MeshBasicMaterial({color,depthTest:false}));mark.position.copy(point(p,25));mark.renderOrder=9;group.add(mark);let tag=label(name);tag.position.copy(point(p,110));group.add(tag)}if(pending){for(const [p,h1] of [[base,4],...relays.map(p=>[p,3]),[goal,2],[goal2,2]]){const geo=new THREE.BufferGeometry().setFromPoints([point(p,h1),point(pending,3)]),line=new THREE.Line(geo,new THREE.LineDashedMaterial({color:0xffd166,dashSize:60,gapSize:35,depthTest:false}));line.computeLineDistances();line.renderOrder=8;group.add(line)}}};update3d();let down;const ray=new THREE.Raycaster(),pos=new THREE.Vector2();renderer.domElement.addEventListener('pointerdown',e=>down=[e.clientX,e.clientY]);renderer.domElement.addEventListener('pointerup',e=>{if(!down||Math.hypot(e.clientX-down[0],e.clientY-down[1])>5)return;const r=renderer.domElement.getBoundingClientRect();pos.set((e.clientX-r.left)/r.width*2-1,-(e.clientY-r.top)/r.height*2+1);ray.setFromCamera(pos,camera);const hit=ray.intersectObject(mesh)[0];if(hit)choosePoint([hit.point.x+2750,hit.point.z+4250])});new ResizeObserver(()=>{const w=el.clientWidth;if(!w)return;renderer.setSize(w,h);camera.aspect=w/h;camera.updateProjectionMatrix()}).observe(el);function animate(){controls.update();renderer.render(scene,camera);requestAnimationFrame(animate)}animate()}
